package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class Performance70Test {
 @Test public void fastModeIsPersistentAndDefaultsBalanced()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();a.getSharedPreferences("config",0).edit().remove("fastPerformance").commit();Field tab=MainActivity.class.getDeclaredField("tab");tab.setAccessible(true);tab.set(a,3);Method render=MainActivity.class.getDeclaredMethod("render");render.setAccessible(true);render.invoke(a);Switch s=(Switch)AutoBashUiTest.find(a.findViewById(android.R.id.content),"Fast performance mode");assertNotNull(s);assertFalse(s.isChecked());s.performClick();assertTrue(a.getSharedPreferences("config",0).getBoolean("fastPerformance",false));a.finish();}
 @Test public void exactFileFingerprintReusesContentNotFilenames()throws Exception{TapService s=Robolectric.buildService(TapService.class).create().get();File a=new File(s.getCacheDir(),"a.png"),b=new File(s.getCacheDir(),"b.png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(a)){out.write(new byte[]{1,2,3});}try(java.io.FileOutputStream out=new java.io.FileOutputStream(b)){out.write(new byte[]{1,2,3});}Method m=TapService.class.getDeclaredMethod("fingerprint",File.class);m.setAccessible(true);assertEquals(m.invoke(s,a),m.invoke(s,b));try(java.io.FileOutputStream out=new java.io.FileOutputStream(b)){out.write(new byte[]{1,2,3,4});}assertNotEquals(m.invoke(s,a),m.invoke(s,b));s.onDestroy();}
 @Test public void workerCountsRemainBounded()throws Exception{TapService s=Robolectric.buildService(TapService.class).create().get();SharedPreferences p=s.getSharedPreferences("config",0);Field prefs=TapService.class.getDeclaredField("prefs");prefs.setAccessible(true);prefs.set(s,p);Method m=TapService.class.getDeclaredMethod("scanWorkers");m.setAccessible(true);p.edit().putBoolean("fastPerformance",false).commit();int balanced=(Integer)m.invoke(s);p.edit().putBoolean("fastPerformance",true).commit();int fast=(Integer)m.invoke(s);assertTrue(balanced>=1&&balanced<=2);assertTrue(fast>=balanced&&fast<=4);assertTrue(fast<=Runtime.getRuntime().availableProcessors());s.onDestroy();}
}
